const rows = $input.all().map(i => i.json).filter(a => a && a.link);
if (rows.length === 0) return [];
return [{ json: { rows } }];

const cfg = $('Config').first().json;
const rows = $input.first().json.rows;
if (!cfg.AI_ENABLED || rows.length === 0) return [{ json: { skip: true, prompt: 'Reply with {}' } }];
// one prompt per browser-release batch instead of per CVE
const seenBatch = new Set();
const picked = [];
for (const r of rows) {
  if (r.batch_key) { if (seenBatch.has(r.batch_key)) continue; seenBatch.add(r.batch_key); }
  picked.push(r);
  if (picked.length >= cfg.AI_MAX_PER_RUN) break;
}
return picked.map(r => ({ json: { key: r.batch_key || r['link'], prompt:
  `${cfg.AI_CONTEXT}\nYou write short threat-intel notes for our SOC analysts. Keep summary under 60 words and why under 45 words. Reply with JSON only, no markdown, exactly this shape: {"summary":"2 plain-English sentences on what happened","why":"1 sentence on why it matters (or does not) for our clients and what to do","relevant":true|false}\n\n` + `Article title: ${r.title}\nSource: ${r.source}\nFeed text: ${(r.summary || '').slice(0, 900)}` } }));

const parseAi = (item) => {
  try {
    const j = item.json || {};
    if (j.error || !j.content) return null;
    let text = (j.content || []).map(c => c.text || '').join('').trim();
    text = text.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const start = text.indexOf('{'); const end = text.lastIndexOf('}');
    if (start < 0 || end < 0) return null;
    return JSON.parse(text.slice(start, end + 1));
  } catch { return null; }
};

const rows = $('Rows').first().json.rows;
const prep = $('Prep AI').all();
const byKey = {};
$input.all().forEach((item, i) => { const k = prep[i]?.json?.key; const p = k ? parseAi(item) : null; if (k && p) byKey[k] = p; });
let summarised = 0;
for (const r of rows) {
  const p = byKey[r.batch_key] || byKey[r['link']];
  if (p) { r.ai_summary = String(p.summary || '').slice(0, 600); r.ai_reason = String(p.why || p.action || '').slice(0, 400); if (typeof p.relevant === 'boolean') r.ai_verdict = p.relevant; summarised++; }
}

return [{ json: { rows, summarised } }];
